package ru.controlexpenses; import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{ FrameLayout c; public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);c=findViewById(R.id.content); findViewById(R.id.add).setOnClickListener(v->add());findViewById(R.id.menu).setOnClickListener(v->menu()); home();} void home(){c.removeAllViews();LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(16,20,16,10);TextView t=new TextView(this);t.setText("Расходы\n\nПока нет расходов");t.setTextSize(22);t.setTextColor(Color.rgb(30,45,55));l.addView(t);c.addView(l);} void add(){new AlertDialog.Builder(this).setTitle("Добавить расход").setItems(new String[]{"📷 Сканировать чек","🖼 Выбрать из галереи","✍ Ввести вручную"},(d,w)->{if(w<2){Intent i=new Intent(this,ReceiptActivity.class);i.putExtra("source",w);startActivity(i);}else Toast.makeText(this,"Откроется форма ручного расхода",Toast.LENGTH_SHORT).show();}).show();} void menu(){final String[] x={"Расходы","Категории","Проекты","Отчёты","Валюты"};new AlertDialog.Builder(this).setTitle("Меню").setItems(x,null).show();}}